import hashlib
import hmac
import datetime

class Archiver:
    def __init__(self, db_records):
        self.db_records = db_records

    def archive_old_records(self):
        current_time = datetime.datetime.now()
        archived_records = {}
        for record_id in self.db_records:
            record = self.db_records[record_id]
            modified_time = record['modified_time']
            if (current_time - modified_time).days > 365:
                archived_records[record_id] = record
        return archived_records

    def verify_signature(self, data, signature, secret_key):
        calculated_signature = hmac.new(secret_key.encode(), data.encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(calculated_signature, signature):
            return True
        return False

