import hmac

class FinancialReconciliation:
    def __init__(self, transactions, secret_key):
        self.transactions = transactions
        self.secret_key = secret_key

    def verify_signature(self, signature, message):
        expected_signature = hmac.new(self.secret_key.encode(), message.encode(), "sha256").hexdigest()
        if hmac.compare_digest(expected_signature, signature):
            return True
        return False

    def reconcile(self):
        result = []
        for transaction in self.transactions:
            if "signature" in transaction and "amount" in transaction and "description" in transaction:
                if self.verify_signature(transaction["signature"], transaction["description"]):
                    result.append(transaction)
        return result

def transactions_generator(transactions):
    for transaction in transactions:
        yield transaction

