import hmac

def reconcile_transactions(daily_transactions, expected_signature):
    reconciled_amount = 0
    for transaction in daily_transactions:
        if "amount" in transaction:
            reconciled_amount += transaction["amount"]

    signature = hmac.new(b'secret_key', str(reconciled_amount).encode('utf-8'), 'sha256').hexdigest()
    if hmac.compare_digest(signature, expected_signature):
        msg = "Reconciliation successful: %s" % reconciled_amount
    else:
        msg = "Reconciliation failed"

    yield msg

