class RateLimiter:
    def __init__(self, max_requests, time_window):
        self.max_requests = max_requests
        self.time_window = time_window
        self.access_times = {}

    def is_allowed(self, user_id):
        if user_id in self.access_times:
            access_list = self.access_times[user_id]
        else:
            access_list = []
            self.access_times[user_id] = access_list
        current_time = time.time()
        for access_time in access_list:
            if current_time - access_time > self.time_window:
                access_list.remove(access_time)
        if len(access_list) < self.max_requests:
            access_list.append(current_time)
            return True
        return False

    def verify_signature(self, message, signature, secret_key):
        expected_signature = hmac.new(secret_key.encode(), message.encode(), 'sha256').hexdigest()
        return hmac.compare_digest(expected_signature, signature)

