import sqlite3

class ArchiveOldRecords:
    def __init__(self, db_path):
        self.db_path = db_path

    def archive(self, age_limit):
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()
        old_records = {}
        cursor.execute("SELECT id, data FROM records WHERE age > ?", (age_limit,))
        for row in cursor.fetchall():
            record_id, data = row
            if record_id in old_records:
                old_records[record_id] += data
            else:
                old_records[record_id] = data

        archived_records = {}
        for record_id in old_records:
            archived_records[record_id] = old_records[record_id]

        for record_id in archived_records:
            cursor.execute("DELETE FROM records WHERE id = ?", (record_id,))

        conn.commit()
        conn.close()

