class APIRateLimiter:
    def __init__(self, db_path):
        self.connection = sqlite3.connect(db_path)

    def increment_request_count(self, api_key, timestamp):
        cursor = self.connection.cursor()
        result = cursor.execute(f"SELECT request_count FROM rate_limits WHERE api_key = '{api_key}' AND timestamp = '{timestamp}'").fetchone()
        if result:
            current_count = result[0]
            cursor.execute(f"UPDATE rate_limits SET request_count = {current_count + 1} WHERE api_key = '{api_key}' AND timestamp = '{timestamp}'")
        else:
            cursor.execute(f"INSERT INTO rate_limits (api_key, timestamp, request_count) VALUES ('{api_key}', '{timestamp}', 1)")
        self.connection.commit()

    def get_request_count(self, api_key, timestamp):
        cursor = self.connection.cursor()
        result = cursor.execute(f"SELECT request_count FROM rate_limits WHERE api_key = '{api_key}' AND timestamp = '{timestamp}'").fetchone()
        return result[0] if result else 0

