import re
import os

def sanitize_html(user_input):
    allowed_tags = re.compile(r'<(b|i|u)>|</(b|i|u)>')
    return ''.join([line for line in user_input.splitlines() if allowed_tags.search(line)])

def save_comment(username, comment):
    base_path = 'comments/'
    user_path = os.path.join(base_path, username)
    if not os.path.exists(user_path):
        os.makedirs(user_path)
    filepath = os.path.join(base_path, username, 'comment.txt')
    with open(filepath, 'w') as f:
        f.write(comment)
